function af(string $section,string $key,string $label,string $type='text',array $options=[]): void {
 global $c;$v=$c[$section][$key]??'';$name=$section.'['.$key.']';
 echo '<label class="field'.($type==='checkbox'?' check-field':'').'"><span>'.cs_e($label).'</span>';
 if($type==='checkbox'){echo '<input type="checkbox" name="'.cs_e($name).'" value="1" '.(!empty($v)?'checked':'').'>';}
 elseif($type==='textarea')echo '<textarea name="'.cs_e($name).'" rows="4">'.cs_e($v).'</textarea>';
 elseif($type==='select'){echo '<select name="'.cs_e($name).'">';foreach($options as $val=>$text)echo '<option value="'.cs_e($val).'" '.((string)$v===(string)$val?'selected':'').'>'.cs_e($text).'</option>';echo '</select>';}
 else echo '<input type="'.cs_e($type).'" name="'.cs_e($name).'" value="'.cs_e($v).'" '.($type==='number'?'step="1"':'').'>';
 echo '</label>';
}
function af_upload(string $group,string $key,string $name,string $label,bool $video=false): void {
 af($group,$key,$label.' — bestandspad of https-link');echo '<label class="field"><span>Of upload een bestand</span><input type="file" name="'.cs_e($name).'" accept="'.($video?'video/mp4,video/webm':'image/png,image/jpeg,image/webp,image/gif').'"></label>';
}
